1	// Fresh-path wiring convergence (task-code-work DESIGN §7, the primitive
2	// absorbed from #405). The deterministic half of the self-refresh that
3	// has nothing to do with the vendored mount's CONTENT: the repo-specific wiring a
4	// scheduled Claudinite consumer must carry, converged idempotently in code so the
5	// nightly refresh never needs a model to re-enact bootstrap's prose.
6	//
7	// One source of truth: bootstrap Part 5 (the settings hooks) + Part 6 (the
8	// scheduler workflow) describe this same set for a fresh adoption; this module is
9	// what both bootstrap and the update flows CALL, so the wiring can never drift between
10	// "how a repo is set up" and "how the nightly keeps it set up".
11	//
12	// Operates on a repo working tree at `root` with node:fs directly (like
13	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
14	// repo already converged produces an empty change list.
15	
16	import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
17	import { join, dirname, relative, sep } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { hashedCron } from './hash-minute.mjs';
20	import { DEFAULT_SCHEDULE } from './calendar.mjs';
21	import { writeRulesIndex, RULES_INDEX_FILE, RULES_INDEX_IMPORT } from '../pack_loader/generate-rules-index.mjs';
22	import { LOCAL_PACKS_SUBDIR, LOCAL_DECL_PREFIX, SHARED_SUBDIR } from '../pack_loader/pack-registry.mjs';
23	import { settingsPath } from '../settings-file.mjs';
24	import { ENDPOINTS_KEY, LEGACY_ENDPOINTS_KEY } from '../checks/helpers/repo-context.mjs';
25	
26	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
27	// Ensured present without clobbering — a set-union keyed on the command string, so
28	// a repo's own extra hooks and any hand-added entries survive untouched.
29	export const REQUIRED_HOOKS = [
30	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
31	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
32	  { event: 'PreToolUse', matcher: 'Bash', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
33	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
34	];
35	
36	export const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';
37	// The queue's second workflow (tasks-dispatch DESIGN §14). The first one keeps the
38	// path above: `claudinite-scheduler.yml` holds the scheduler run and its drain, so the repo
39	// still has exactly one cron at one well-known path.
40	export const EXECUTOR_WORKFLOW = '.github/workflows/claudinite-executor.yml';
41	export const SETTINGS_PATH = '.claude/settings.json';
42	export const CLAUDE_MD = 'CLAUDE.md';
43	export const README = 'README.md';
44	
45	// The pack-badge row: the marks of the packs this repo declares, on a single
46	// line of its README. Adoption seeds it and the repo owns it from there — which
47	// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
48	// by bootstrap alone) rather than converged like the surfaces around it. A
49	// README belongs to its repo: a nightly that re-derived this row would rewrite a
50	// member's README every time its declaration moved, so the nightly stays out and
51	// a stale row is the repo's to fix (re-run the converge with `--badges`).
52	//
53	// Delimited by HTML comments rather than located by position, so the row can be
54	// re-converged in place wherever the repo has moved it, and so anything the repo
55	// writes AFTER the closing marker on the same line (a tagline, a build badge) is
56	// its own and survives untouched — which is why the CLOSING marker stays inline,
57	// at the end of the badges' own line.
58	//
59	// The OPENING marker gets a line to itself, and that newline is load-bearing: a
60	// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
61	// through the line carrying `-->` is then emitted as raw HTML. Put the badges
62	// after the opening marker on one line and a README renders the literal text
63	// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
64	// block at the marker, so the badges start a paragraph and parse as markdown.
65	export const BADGE_ROW_START = '<!-- claudinite:packs -->';
66	export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
67	const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
68	
69	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
70	// The whole line (and its trailing newline) is removed wherever it appears.
71	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
72	
73	// The project's settings, loaded through the one reader that validates them.
74	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
75	// so the cross-tree import stays a single, reviewable edge.
76	const repoConfig = async (root) => (await import('../checks/helpers/repo-context.mjs')).loadConfig(root);
77	
78	// The repo Actions secrets its scheduled tasks declare via `required_secrets`,
79	// deduped and sorted. Async because task discovery is; pure otherwise.
80	export async function declaredSecrets(root, config) {
81	  const { discoverTasks } = await import('./discover.mjs');
82	  const { tasks } = await discoverTasks(root, config);
83	  const names = tasks.flatMap((t) => t.decl?.required_secrets ?? []);
84	  // Endpoint tokens ride the same rail (tasks-dispatch DESIGN §12, §14.6): the
85	  // config maps an endpoint name to a URL and to the NAME of the Actions secret
86	  // holding its token, and the stamp puts that name in the executor's env exactly
87	  // as a `required_secrets` entry. The executor reads it only at the moment of the
88	  // invocation call; nothing else in a task's life ever sees it.
89	  const endpointTokens = Object.values(config?.taskScheduler?.[ENDPOINTS_KEY] ?? config?.taskScheduler?.[LEGACY_ENDPOINTS_KEY] ?? {})
90	    .map((e) => e?.tokenSecret).filter((n) => typeof n === 'string' && n);
91	  return [...new Set([...names, ...endpointTokens])].sort();
92	}
93	
94	// Stamp the declared secrets into the scheduler workflow's engine step, beside
95	// GITHUB_TOKEN. This is the whole delivery mechanism: GitHub Actions requires each
96	// secret to be named statically in the workflow, and a task's `required_secrets` is
97	// exactly that list — so the wiring converge writes it, and a worker then reads
98	// `process.env.<NAME>` like any other environment variable. No bundle, no parsing,
99	// no engine-side selection. Regenerated from the stub each converge, so the list
100	// tracks the declarations rather than accumulating.
101	// A stub says WHERE with the `# claudinite:secrets` marker, and the scheduler run stub needs
102	// that: it has two jobs carrying GITHUB_TOKEN and only the executing one may see a
103	// secret. The fallback under the GITHUB_TOKEN line covers a stub that declares no
104	// marker.
