107	  if (!names.length) return stubText;
108	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
109	  // MARKER OR NOTHING. The fallback this used to carry — stamp under the first
110	  // `GITHUB_TOKEN` line — was safe only while every stub that reached here ran task
111	  // code. The scheduler run stub no longer does (its drain dispatches the executor rather
