294	// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
295	// would hold in another repo belongs in a canon pack instead — propose it upstream.
296	//
297	// The id is this directory's name and the prose is the RULES.md beside this file —
298	// both by convention (engine/pack_loader/pack-conventions.mjs), so neither is
299	// declared here.
300	export default {
301	  version: 1,
302	  ruleRoutingGuidance: {
303	    belongs: 'everything specific to this repository and portable nowhere else: its working rules, and the checks, skills and tasks carrying them',
304	    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
305	  },
306	  detect: null,
307	  marker: null,
308	  worldRules: [],
309	};
310	`;
