343	export function seedRepoLocalPack(root, fullName) {
344	  const id = packIdForRepo(fullName);
345	  if (!id) return null;
346	  const dir = join(root, LOCAL_PACKS_SUBDIR, id);
347	  if (existsSync(dir)) return null;
348	
349	  const settingsFile = settingsPath(root);
350	  let raw;
351	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); } catch { return null; }
352	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
