496	// CLI: `node converge-wiring.mjs [owner/repo] [--badges] [--seed-local-pack]` —
497	// converge THIS repo's wiring. The full name comes from argv or
498	// GITHUB_REPOSITORY/CLAUDINITE_REPO; the scheduler stub from the vendored mount. This
499	// is the single surface bootstrap (Part 6) and the update flows both invoke, so the
500	// wiring set is defined once, here — and the two flags are the whole difference
501	// between them. Both are ONE-TIME SEEDS of files the repo then owns (the README badge
502	// row, the repo's own local pack), which is exactly why the nightly must not pass
503	// them: it would rewrite a row the owner moved, or resurrect a pack they deleted.
504	async function main() {
505	  const argv = process.argv.slice(2);
506	  const badges = argv.includes('--badges');
507	  const seedLocalPack = argv.includes('--seed-local-pack');
508	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
509	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
510	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
511	  const config = await repoConfig(root);
512	  // The repo's one cron workflow is the queue's scheduler run and its drain, at the path the
513	  // slot scheduler used to hold — so the one-cron rule and every reader that knows
514	  // this workflow by name keep holding across the retirement.
515	  const stubs = join(root, '.claudinite/shared/engine/scheduler/stubs');
516	  const stubPath = join(stubs, 'claudinite-scheduler.yml');
517	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
