519	    ? readFileSync(join(stubs, 'claudinite-executor.yml'), 'utf8') : null;
520	  const secretNames = await declaredSecrets(root, config);
521	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames, { badges, seedLocalPack, executorStub, dailyHour: config?.taskScheduler?.dailyHour });
522	  if (error) console.log(`! ${error}`);
523	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
524	}
525	
526	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
